// Remove artigos repetidos (o mesmo texto aparecia duas vezes com títulos levemente diferentes).
const normalize = (text: string) => text.replace(/["“”]/g, "").replace(/\s+/g, " ").slice(0, 120);
const seen = new Set<string>();
export const SUMMARY_ITEMS: SummaryItem[] = RAW_ITEMS.filter((item) => {
  const key = normalize(item.content);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});
